window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ea0860b3f04e754f"]={"versions": [{"id": "FIG-ea0860b3f04e754f", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR Security Extract Template (Adaptive Platform). Dargestellt ist die Struktur zur Modellierung der Netzwerkkonfiguration einer <code>IdsmInstance</code> über plattformspezifische Instanziierungs- und Endpunkt-Konfigurationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>IdsmInstance</code> (spezialisiert <code>IdsCommonElement</code>): Besitzt die optionalen Attribute <code>idsmInstanceId: PositiveInteger [0..1]</code> und <code>timestampFormat: String [0..1]</code>. Referenziert per gerichteter Assoziation mit Stereotyp <code>«atpSplitable»</code> über die Rolle <code>+idsmModuleInstantiation</code> mit Kardinalität <code>0..1</code> ein Element vom Typ <code>IdsmModuleInstantiation</code>.</li>\n<li><code>IdsmModuleInstantiation</code>: Spezialisiert per Generalisierungspfeil die abstrakte Klasse <code>IdsPlatformInstantiation</code>.</li>\n<li><code>IdsPlatformInstantiation</code>: Abstrakte Klasse (kursiv dargestellt), referenziert über die gerichtete Assoziationsrolle <code>+networkInterface</code> mit Kardinalität <code>0..1</code> ein Element vom Typ <code>PlatformModuleEthernetEndpointConfiguration</code>.</li>\n<li><code>PlatformModuleEthernetEndpointConfiguration</code>: Spezialisiert per Generalisierungspfeil das <code>ARElement</code> <code>PlatformModuleEndpointConfiguration</code>. Verfügt über die Attribute:</li>\n<li><code>ipv4MulticastIpAddress: Ip4AddressString [0..1]</code></li>\n<li><code>ipv6MulticastIpAddress: Ip6AddressString [0..1]</code></li>\n<li><code>tcpPort: PositiveInteger [0..1]</code></li>\n<li><code>udpPort: PositiveInteger [0..1]</code></li>\n<li><code>PlatformModuleEndpointConfiguration</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>ARElement</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzabläufe. Die Instanziierung erfolgt deklarativ innerhalb der AUTOSAR-Modellierung zur Bereitstellung von Sicherheits- und Netzwerkkonfigurationen auf der Adaptive Platform.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Konfiguration des Intrusion Detection System Managers (IdsM) im Security Extract:</p>\n<ul class=\"fig-list\">\n<li>Die Anbindung an die Netzwerkschnittstelle erfolgt über die optionale Referenz <code>networkInterface</code> auf eine <code>PlatformModuleEthernetEndpointConfiguration</code>.</li>\n<li>Die Port-Konfiguration für Multicast-/Netzwerkkommunikation wird direkt in <code>PlatformModuleEthernetEndpointConfiguration</code> über <code>tcpPort</code> und <code>udpPort</code> abgebildet, ergänzt um optionale IPv4- oder IPv6-Multicast-Adressen.</li>\n<li><code>IdsmInstance</code> bindet die Instanziierung über eine splitbare Referenz (<code>«atpSplitable»</code>) ein.</li>\n</ul>"}, {"id": "FIG-465ef53429aec514", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR Security Extract Template (Adaptive Platform). Dargestellt ist die Struktur zur Modellierung der Netzwerkkonfiguration einer <code>IdsmInstance</code> über plattformspezifische Instanziierungs- und Endpunkt-Konfigurationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>IdsmInstance</code> (spezialisiert <code>IdsCommonElement</code>): Besitzt die optionalen Attribute <code>idsmInstanceId: PositiveInteger [0..1]</code> und <code>timestampFormat: String [0..1]</code>. Referenziert per gerichteter Assoziation mit Stereotyp <code>«atpSplitable»</code> über die Rolle <code>+idsmModuleInstantiation</code> mit Kardinalität <code>0..1</code> ein Element vom Typ <code>IdsmModuleInstantiation</code>.</li>\n<li><code>IdsmModuleInstantiation</code>: Spezialisiert per Generalisierungspfeil die Klasse <code>IdsPlatformInstantiation</code>.</li>\n<li><code>IdsPlatformInstantiation</code>: Spezialisiert die abstrakte Oberklasse <code>NonOsModuleInstantiation</code> (kursiv dargestellt) und referenziert über die gerichtete Assoziationsrolle <code>+networkInterface</code> mit Kardinalität <code>0..1</code> ein Element vom Typ <code>PlatformModuleEthernetEndpointConfiguration</code>.</li>\n<li><code>PlatformModuleEthernetEndpointConfiguration</code>: Spezialisiert per Generalisierungspfeil das <code>ARElement</code> <code>PlatformModuleEndpointConfiguration</code>. Verfügt über die Attribute:</li>\n<li><code>ipv4MulticastIpAddress: Ip4AddressString [0..1]</code></li>\n<li><code>ipv6MulticastIpAddress: Ip6AddressString [0..1]</code></li>\n<li><code>PlatformModuleEndpointConfiguration</code>: Abstrakte Metaklasse (kursiv dargestellt), spezialisiert <code>ARElement</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzabläufe. Die Instanziierung erfolgt deklarativ innerhalb der AUTOSAR-Modellierung zur Bereitstellung von Sicherheits- und Netzwerkkonfigurationen auf der Adaptive Platform.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Konfiguration des Intrusion Detection System Managers (IdsM) im Security Extract:</p>\n<ul class=\"fig-list\">\n<li>Die Anbindung an die Netzwerkschnittstelle erfolgt über die optionale Referenz <code>networkInterface</code> auf eine <code>PlatformModuleEthernetEndpointConfiguration</code>.</li>\n<li><code>PlatformModuleEthernetEndpointConfiguration</code> kapselt ausschließlich Multicast-Adressparameter (<code>ipv4MulticastIpAddress</code> und <code>ipv6MulticastIpAddress</code>); dedizierte Port-Attribute (<code>tcpPort</code>, <code>udpPort</code>) sind auf dieser Ebene nicht definiert.</li>\n<li><code>IdsPlatformInstantiation</code> ist in die Typhierarchie von <code>NonOsModuleInstantiation</code> eingebettet.</li>\n<li><code>IdsmInstance</code> bindet die Instanziierung über eine splitbare Referenz (<code>«atpSplitable»</code>) ein.</li>\n</ul>"}], "trans": [{"from": "FIG-ea0860b3f04e754f", "to": "FIG-465ef53429aec514", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Klasse <code>IdsPlatformInstantiation</code>: Spezialisierung von <code>NonOsModuleInstantiation</code> hinzugefügt (Generalisierungsbeziehung auf die zusätzliche Oberklasse).</li>\n<li>Klasse <code>PlatformModuleEthernetEndpointConfiguration</code>: Attribute <code>tcpPort: PositiveInteger [0..1]</code> und <code>udpPort: PositiveInteger [0..1]</code> entfernt.</li>\n</ul>"}]};
